
let voiceCache={en:[],pt:[]}; let voicesReady=false;
function refreshVoices(){const all=speechSynthesis.getVoices(); if(all.length===0) return; voicesReady=true; voiceCache.en=all.filter(v=>v.lang.toLowerCase().startsWith('en')); voiceCache.pt=all.filter(v=>v.lang.toLowerCase().startsWith('pt')); }
refreshVoices(); if(speechSynthesis.onvoiceschanged!==undefined) speechSynthesis.onvoiceschanged=refreshVoices;
function getVoiceEN(){if(!voicesReady) refreshVoices(); return voiceCache.en.find(v=>v.lang==='en-US') || voiceCache.en[0] || null;}
function getVoicePT(){if(!voicesReady) refreshVoices(); return voiceCache.pt.find(v=>v.lang==='pt-BR') || voiceCache.pt[0] || null;}
function speakEnglish(text,rate=0.9,onEnd){if(!text) return; if(typeof soundOn!=='undefined' && !soundOn) return; speechSynthesis.cancel(); setTimeout(()=>{const u=new SpeechSynthesisUtterance(text); u.lang='en-US'; u.rate=rate; const v=getVoiceEN(); if(v) u.voice=v; if(onEnd) u.onend=onEnd; speechSynthesis.speak(u);},80);}
function speakPortuguese(text,rate=1.0,onEnd){if(!text) return; if(typeof soundOn!=='undefined' && !soundOn) return; const isEnglishOnly=/^[A-Za-z0-9 .,!?'"-]+$/.test(text) && !/[áàâãéêíóôõúç]/.test(text) && /\b(hello|my name|I am|would like|coffee|please)\b/i.test(text); if(isEnglishOnly){speakEnglish(text,rate,onEnd); return;} speechSynthesis.cancel(); setTimeout(()=>{const u=new SpeechSynthesisUtterance(text); u.lang='pt-BR'; u.rate=rate; const v=getVoicePT(); if(v) u.voice=v; if(onEnd) u.onend=onEnd; speechSynthesis.speak(u);},80);}
function speakBilingual(en,pt){speakEnglish(en,0.88,()=>{setTimeout(()=>speakPortuguese(pt,1.0),600);});}
function speakSlow(en){speakEnglish(en,0.55);}
function speak(text){speakEnglish(text);}
const DATA_VERSION='2026-08-23-clean-lessons-v2';
if(localStorage.getItem('zeuvastec-data-version')!==DATA_VERSION){
  ['zeuvastec-completed','zeuvastec-points','zeuvastec-activity-days','zeuvastec-daily','zeuvastec-review-priority-lessons','zeuvastec-known-words'].forEach(k=>localStorage.removeItem(k));
  localStorage.setItem('zeuvastec-data-version',DATA_VERSION);
}
let completed=JSON.parse(localStorage.getItem('zeuvastec-completed')||'[]');
let points=parseInt(localStorage.getItem('zeuvastec-points')||'0',10);
let currentCard=0; let soundOn=true; let activeTab='dialog'; let currentQuizIndex=0;
const $=s=>document.querySelector(s); const $$=s=>document.querySelectorAll(s);
function save(){localStorage.setItem('zeuvastec-completed',JSON.stringify(completed)); localStorage.setItem('zeuvastec-points',points.toString());}

// --- Meta diária (anel de progresso do dia) ---
const DAILY_GOAL_UNITS=10; // representa os "10 minutos" da meta diária
const dailyKey='zeuvastec-daily';
function todayStr(){return new Date().toISOString().slice(0,10);}
let dailyData=JSON.parse(localStorage.getItem(dailyKey)||'null');
if(!dailyData||dailyData.date!==todayStr()){dailyData={date:todayStr(),units:0};}
function saveDaily(){localStorage.setItem(dailyKey,JSON.stringify(dailyData));}
function updateDailyRing(){
  const pct=Math.min(100,Math.round((dailyData.units/DAILY_GOAL_UNITS)*100));
  const dp=document.getElementById('daily-progress'); if(dp) dp.textContent=pct+'%';
  const ring=document.querySelector('.ring');
  if(ring){
    ring.style.border='6px solid #d7e793';
    ring.style.borderTopColor='#d7e793';
    ring.style.background = pct>0 ? `conic-gradient(var(--green) ${pct}%, #d7e793 0)` : 'transparent';
  }
}
function resetDailyVisual(){ updateDailyRing(); }
function addDailyProgress(units){dailyData.units+=units; saveDaily(); updateDailyRing();}

