const filteredLessonIds = new Set(lessons.map(l => l.id));
completed = completed.filter(id => filteredLessonIds.has(id));
save();

function renderLessons(){
 const nextIdx=lessons.findIndex(l=>!completed.includes(l.id));
 const start=nextIdx===-1?0:nextIdx;
 const upcoming=lessons.slice(start,start+3);
 const grid=document.getElementById('lesson-grid');
 if(grid) grid.innerHTML=upcoming.map(l=>`<article class="lesson-card ${completed.includes(l.id)?'done':''}"><span class="number">${String(l.id).padStart(2,'0')}</span>${completed.includes(l.id)?'<span class="check">✓</span>':''}<span class="level-badge">${l.level}</span><h3>${l.title}</h3><p>${l.desc} · ${l.time} · ${l.quiz.length} perguntas</p><button data-lesson="${l.id}">${completed.includes(l.id)?'Refazer':'Começar'} →</button></article>`).join('');
 const modules=[...new Set(lessons.map(l=>Number(l.module)).filter(Number.isFinite))].sort((a,b)=>a-b);
 const moduleNames={1:'Foundations',2:'Everyday Life',3:'Communication',4:'Work & Life',5:'Professional English',6:'Fluency Mastery'};
 const moduleIcons={1:'🌱',2:'☕',3:'💬',4:'💼',5:'🎓',6:'🏆'};
 const mg=document.getElementById('modules-grid');
 if(mg){
   mg.innerHTML=modules.map(m=>{
     const ml=lessons.filter(x=>Number(x.module)===m);
     if(!ml.length) return '';
     const done=ml.filter(x=>completed.includes(x.id)).length;
     const pct=Math.round(done/ml.length*100);
     return `<article class="module-card"><div class="module-card-top"><span class="module-icon">${moduleIcons[m]||'📘'}</span><span class="module-badge">MÓDULO ${m}</span></div><h3>${moduleNames[m]||ml[0].moduleName||('Módulo '+m)}</h3><p>${ml[0].title} → ${ml[ml.length-1].title}</p><div class="module-progress"><i style="width:${pct}%"></i></div><small style="color:#718078;font-size:11px">${done}/${ml.length} lições · ${pct}% concluído</small></article>`
   }).join('');
 }
 const grouped={}; lessons.forEach(l=>{if(!grouped[l.module]) grouped[l.module]=[]; grouped[l.module].push(l);});
 let html='';
 Object.keys(grouped).sort((a,b)=>a-b).forEach(mod=>{
   const ml=[...grouped[mod]].sort((a,b)=>Number(completed.includes(a.id))-Number(completed.includes(b.id))||a.id-b.id);
   html+=`<div class="catalog-head"><h3>Módulo ${mod} — ${ml[0].moduleName} (${ml.length} lições)</h3><span class="level-badge">${ml.filter(x=>completed.includes(x.id)).length}/${ml.length} · ${ml.length*12} perguntas</span></div><div class="lesson-catalog">`+ml.map(l=>{const done=completed.includes(l.id);return `<article class="catalog-card ${done?'done':''}"><div><span class="level-badge">${done?'CONCLUÍDA · ':''}${l.level}</span><p class="eyebrow">LIÇÃO ${String(l.id).padStart(3,'0')} · ${l.time}</p><h2>${l.title}</h2><p>${l.desc}</p><small style="font-size:11px;color:#276246">📝 ${l.quiz.length} perguntas · ${l.vocab.length} palavras · ✅ Tradução verificada</small></div><button data-lesson="${l.id}">${done?'Revisar':'Começar'}</button></article>`}).join('')+`</div>`;
 });
 const cat=document.getElementById('lesson-catalog');
 if(cat) cat.innerHTML=html;
 const cc=document.getElementById('completed-count'); if(cc) cc.textContent=completed.length;
 const pts=document.getElementById('points'); if(pts) pts.textContent=points;
}
function openLesson(id){
 const l=lessons.find(x=>x.id===id);
 currentQuizIndex=0;
 const tabs=`<div class="tabs"><button class="tab active" data-tab="dialog">Diálogo</button><button class="tab" data-tab="vocab">Vocabulário (${l.vocab.length})</button><button class="tab" data-tab="grammar">Gramática</button><button class="tab" data-tab="quiz">Quiz (${l.quiz.length} perguntas)</button></div>`;
 const vocabHtml=`<div style="margin-bottom:12px;padding:10px;background:#f5fae5;border-radius:10px;font-size:12px;color:#276246"><strong>📖 ${l.vocab.length} palavras - Tradução verificada ✅</strong></div><div class="vocab-grid">${l.vocab.map(v=>`<div class="vocab-item" style="border:1px solid #e9e5da;padding:12px;border-radius:10px;background:#fff"><div class="vocab-item-head" style="display:flex;justify-content:space-between;gap:10px;align-items:flex-start"><div class="vocab-text" style="min-width:0"><strong>${v[0]}</strong> — ${v[1]}<br><small style="color:#718078">${v[2]}</small><br><small style="color:#9ca3af;font-size:11px">💡 ${v[3]||"Expressão útil"}</small></div><div class="vocab-audio-buttons" style="display:flex;flex-direction:column;gap:4px;flex:0 0 auto"><button type="button" class="tab vocab-audio-btn" data-voice-lang="en" data-voice-text="${encodeURIComponent(v[0])}" title="Ouvir em inglês" aria-label="Ouvir em inglês" style="font-size:10px">🔊 EN</button><button type="button" class="tab vocab-audio-btn" data-voice-lang="pt" data-voice-text="${encodeURIComponent(v[1])}" title="Ouvir em português" aria-label="Ouvir em português" style="font-size:10px">🔊 PT</button></div></div></div>`).join('')}</div>`;
 function getQuizHtml(){
   const q = l.quiz[currentQuizIndex];
   if(!q._shuffled || q._shuffledQuestion !== currentQuizIndex){
     const correctOpt = q.opts[q.ans];
     let shuffled = [...q.opts];
     for(let i=shuffled.length-1; i>0; i--){
       const j=Math.floor(Math.random()*(i+1));
       [shuffled[i], shuffled[j]]=[shuffled[j], shuffled[i]];
     }
     q._shuffled = shuffled;
     q._shuffledAns = shuffled.indexOf(correctOpt);
     q._shuffledQuestion = currentQuizIndex;
   }
   const displayOpts = q._shuffled;
   const displayAns = q._shuffledAns;
   q._currentDisplayAns = displayAns;
   return `<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px"><p><span style="background:#e8f4d1;padding:4px 8px;border-radius:999px;font-size:11px;font-weight:700">🌐 Tradução</span> <strong>Pergunta ${currentQuizIndex+1} de ${l.quiz.length}</strong> <span style="background:#dbeafe;padding:2px 6px;border-radius:999px;font-size:10px">🔀 Embaralhado A/B/C/D</span></p></div><p style="font-size:15px;margin:12px 0;font-weight:500">${q.q}</p><div style="display:grid;gap:10px">${displayOpts.map((o,i)=>`<button class="option" style="text-align:left;padding:14px 16px;border:1.5px solid #e9e5da;border-radius:12px;background:#fff;cursor:pointer" data-answer="${i}">${String.fromCharCode(65+i)}. ${o}</button>`).join('')}</div><div id="feedback" style="margin-top:12px;font-weight:700"></div>`;
 }
 function renderModal(){
   return `<p style="font-size:10px;color:#718078;font-weight:700">MÓDULO ${l.module} · ${l.level} · ${l.time} · ${l.quiz.length} PERGUNTAS · ${l.vocab.length} PALAVRAS</p><h2 style="font-family:Fraunces;margin:4px 0">${l.title}</h2><p style="color:#718078;font-size:13px">${l.desc}</p>${tabs}<div id="tab-dialog"><p style="font-family:Fraunces;font-size:22px;color:#276246;margin:16px 0 6px">${l.phrase}</p><p style="color:#718078">${l.translation}</p><div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:12px"><button class="primary" onclick="speakEnglish('${l.phrase.replace(/'/g,"\'")}')">🔊 EN Nativo</button><button class="tab" onclick="speakPortuguese('${l.translation.replace(/'/g,"\'")}')">🔊 PT</button><button class="tab" onclick="speakSlow('${l.phrase.replace(/'/g,"\'")}')">🐢 Devagar</button><button class="tab" onclick="speakBilingual('${l.phrase.replace(/'/g,"\'")}','${l.translation.replace(/'/g,"\'")}')">🔊 Bilíngue</button></div><div style="margin-top:12px;padding:8px;background:#f5fae5;border-radius:8px;font-size:11px;color:#276246">✅ Tradução verificada: ${l.phrase.split(' ').slice(-1)[0]} = ${l.translation.split(' ').slice(-1)[0]}</div></div><div id="tab-vocab" class="hidden">${vocabHtml}</div><div id="tab-grammar" class="hidden"><div style="background:#f5fae5;padding:12px;border-radius:10px">${l.grammar}</div></div><div id="tab-quiz" class="hidden"><div id="quiz-container">${getQuizHtml()}</div></div>`;
 }
 const lessonContent=document.getElementById('lesson-content');
 if(!lessonContent) return;
 lessonContent.innerHTML=renderModal();
 const modal=document.getElementById('lesson-modal');
 if(modal){ modal.classList.remove('hidden'); modal.style.display='grid'; }
 document.querySelectorAll('#lesson-content .tab[data-tab]').forEach(t=>{
   t.onclick=()=>{
     document.querySelectorAll('#lesson-content .tab[data-tab]').forEach(x=>x.classList.remove('active'));
     t.classList.add('active');
     ['dialog','vocab','grammar','quiz'].forEach(k=>{
       const el=document.getElementById('tab-'+k);
       if(el) el.classList.toggle('hidden', k!==t.dataset.tab);
     });
     if(t.dataset.tab==='dialog') speakEnglish(l.phrase);
   };
 });
 function attachQuiz(){
   document.querySelectorAll('#quiz-container [data-answer]').forEach(b=>{
     b.onclick=()=>{
       const q = l.quiz[currentQuizIndex];
       const correct = +b.dataset.answer===(q._currentDisplayAns !== undefined ? q._currentDisplayAns : q.ans);
       const fb=document.getElementById('feedback');
       if(correct){
         fb.innerHTML=`<span style="color:#276246">✅ Correto! +10 XP</span>`;
         b.style.background='#e8f4d1'; b.style.borderColor='#276246';
         points+=10; save();
         setTimeout(()=>{
           if(currentQuizIndex < l.quiz.length-1){
             currentQuizIndex++;
             document.getElementById('quiz-container').innerHTML=getQuizHtml();
             attachQuiz();
           } else {
             fb.innerHTML+=`<br><br><strong style="color:#276246">🎉 Lição concluída! ${l.quiz.length} perguntas · ${l.vocab.length} palavras</strong>`;
             if(!completed.includes(l.id)){ completed.push(l.id); save(); renderLessons(); addDailyProgress(5); if(typeof window.registerPracticeActivity==='function') window.registerPracticeActivity(); updateProgressStats(); }
             speakBilingual('Congratulations! Lesson completed!', 'Parabéns! Lição concluída!');
             setTimeout(()=>{ const nxt=lessons.find(x=>x.id>l.id && !completed.includes(x.id)); if(nxt) openLesson(nxt.id); else { const m=document.getElementById('lesson-modal'); if(m){ m.classList.add('hidden'); m.style.display='none'; } } }, 1800);
           }
         }, 800);
       } else {
         const correctIdx = q._currentDisplayAns !== undefined ? q._currentDisplayAns : q.ans;
         const correctText = q._shuffled ? q._shuffled[correctIdx] : q.opts[q.ans];
         fb.innerHTML=`<span style="color:#dc2626">❌ Quase! A resposta certa é: "${correctText}"</span><br><button class="primary" id="quiz-continue" style="margin-top:12px;padding:10px 16px;font-size:12px">Tentar de novo <span>→</span></button>`;
         b.style.background='#ffe4e6'; b.style.borderColor='#dc2626';
         document.querySelectorAll('#quiz-container [data-answer]').forEach(opt=>{
           opt.style.pointerEvents='none';
           if(+opt.dataset.answer===correctIdx){ opt.style.background='#e8f4d1'; opt.style.borderColor='#276246'; }
         });
         if(!completed.includes(l.id)) addReviewPriorityLesson(l.id);
         const contBtn=document.getElementById('quiz-continue');
         if(contBtn) contBtn.onclick=()=>{
           delete q._shuffled;
           document.getElementById('quiz-container').innerHTML=getQuizHtml();
           attachQuiz();
         };
       }
     };
   });
 }
 attachQuiz();
 speakEnglish(l.phrase);
}
function updateProgressStats(){
  const s=document.getElementById('streak');
  if(s && typeof window.updateZeuvastecStreak==='function') window.updateZeuvastecStreak();
  const p=document.getElementById('points'); if(p) p.textContent=String(points);
  const c=document.getElementById('completed-count'); if(c) c.textContent=String(completed.length);
}
function showView(v){ document.querySelectorAll('.content').forEach(x=>x.classList.add('hidden')); const el=document.getElementById(v+'-view'); if(el) el.classList.remove('hidden'); document.querySelectorAll('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.view===v)); if(v==='progress') updateProgressStats(); if(v==='learn') renderLessons(); if(v!=='talk') window.dispatchEvent(new CustomEvent('maya-stop-conversa')); window.dispatchEvent(new CustomEvent('maya-view-changed',{detail:{view:v}})); }
document.addEventListener('click',e=>{ const lesson=e.target.dataset.lesson; if(lesson) openLesson(+lesson); const view=e.target.closest('[data-view]')?.dataset.view; if(view) showView(view); const say=e.target.dataset.say; if(say) speakEnglish(say); });
const startBtn=document.getElementById('start-lesson'); if(startBtn) startBtn.onclick=()=>{ const nxt=lessons.find(l=>!completed.includes(l.id))||lessons[0]; openLesson(nxt.id); };
const closeBtn=document.getElementById('close-modal'); if(closeBtn) closeBtn.onclick=()=>{ const m=document.getElementById('lesson-modal'); if(m){ m.classList.add('hidden'); m.style.display='none'; } };
const lessonModal=document.getElementById('lesson-modal'); if(lessonModal) lessonModal.onclick=e=>{ if(e.target.id==='lesson-modal'){ e.currentTarget.classList.add('hidden'); e.currentTarget.style.display='none'; } };
const knownWordsKey='zeuvastec-known-words';
function getKnownWords(){ return new Set(JSON.parse(localStorage.getItem(knownWordsKey)||'[]')); }
function saveKnownWords(set){ localStorage.setItem(knownWordsKey, JSON.stringify([...set])); }
const reviewPriorityKey='zeuvastec-review-priority-lessons';
function getReviewPriorityIds(){ return new Set(JSON.parse(localStorage.getItem(reviewPriorityKey)||'[]')); }
function addReviewPriorityLesson(id){ const s=getReviewPriorityIds(); s.add(id); localStorage.setItem(reviewPriorityKey, JSON.stringify([...s])); }
const REVIEW_DECK_SIZE=30; const REVIEW_SOURCE_LESSONS=8;
function buildReviewDeck(){
  const known=getKnownWords();
  const seen=new Set();
  const priorityPool=[];
  const pool=[];
  const priorityIds=getReviewPriorityIds();
  lessons.filter(l=>priorityIds.has(l.id)).forEach(l=>l.vocab.forEach(v=>{ const key=v[0].toLowerCase(); if(!seen.has(key) && !known.has(key)){ seen.add(key); priorityPool.push(v); } }));
  const source=completed.length? lessons.filter(l=>completed.includes(l.id)) : lessons.slice(0,REVIEW_SOURCE_LESSONS);
  source.forEach(l=>l.vocab.forEach(v=>{ const key=v[0].toLowerCase(); if(!seen.has(key) && !known.has(key)){ seen.add(key); pool.push(v); } }));
  if(priorityPool.length===0 && pool.length===0){
    // já revisou tudo disponível: libera novamente as palavras das primeiras lições
    lessons.slice(0,REVIEW_SOURCE_LESSONS).forEach(l=>l.vocab.forEach(v=>{ const key=v[0].toLowerCase(); if(!seen.has(key)){ seen.add(key); pool.push(v); } }));
  }
  for(let i=pool.length-1;i>0;i--){ const j=Math.floor(Math.random()*(i+1)); [pool[i],pool[j]]=[pool[j],pool[i]]; }
  return [...priorityPool, ...pool].slice(0,REVIEW_DECK_SIZE);
}
let words=buildReviewDeck(); let ci=0;
const FLASHCARD_SHELL=`<p class="eyebrow">VOCABULÁRIO · <span id="card-index">1/1</span></p><button class="listen" id="listen-word">🔊</button><div class="flip-scene" id="flip-scene"><div class="flip-card"><div class="flip-face flip-front"><h2 id="word"></h2><p class="flip-hint">Toque para ver a tradução</p><button class="primary" id="flip-card-btn">Virar cartão <span>↻</span></button></div><div class="flip-face flip-back"><p id="translation"></p><small id="example"></small><button class="primary" id="next-card">Eu sei esta palavra <span>→</span></button></div></div></div>`;
function wireFlashcardShell(){
  const nb=document.getElementById('next-card'); if(nb) nb.onclick=markWordKnown;
  const fb=document.getElementById('flip-card-btn'); if(fb) fb.onclick=flipCard;
  const lw=document.getElementById('listen-word'); if(lw) lw.onclick=()=>{ const w=document.getElementById('word'); if(w) speakEnglish(w.textContent); };
}
function renderCard(){
  const flash=document.getElementById('flashcard');
  if(words.length===0){
    if(flash){
      flash.innerHTML=`<p class="eyebrow">VOCABULÁRIO · 0/0</p><h2>Tudo revisado! 🎉</h2><p class="translation">Você concluiu a revisão de hoje.</p><small>Conclua novas lições para desbloquear mais palavras, ou revise novamente agora.</small><button class="primary" id="restart-review" style="margin-top:18px">Revisar novamente <span>↻</span></button>`;
      const rb=document.getElementById('restart-review'); if(rb) rb.onclick=()=>{ words=buildReviewDeck(); ci=0; renderCard(); };
    }
    return;
  }
  if(flash && !document.getElementById('word')){ flash.innerHTML=FLASHCARD_SHELL; wireFlashcardShell(); }
  const c=words[ci]; const w=document.getElementById('word'); const tr=document.getElementById('translation'); const ex=document.getElementById('example'); const idx=document.getElementById('card-index');
  if(w){ w.textContent=c[0]; if(tr) tr.textContent=c[1]; if(ex) ex.textContent=c[2]; if(idx) idx.textContent=(ci+1)+'/'+words.length; }
  const scene=document.getElementById('flip-scene'); if(scene) scene.classList.remove('flipped');
}
function flipCard(){ const scene=document.getElementById('flip-scene'); if(scene) scene.classList.toggle('flipped'); }
function markWordKnown(){
  if(words.length===0){ words=buildReviewDeck(); ci=0; renderCard(); return; }
  const c=words[ci];
  const known=getKnownWords(); known.add(c[0].toLowerCase()); saveKnownWords(known);
  words.splice(ci,1);
  if(ci>=words.length) ci=0;
  points+=2; save();
  const ptsEl=document.getElementById('points'); if(ptsEl) ptsEl.textContent=points;
  addDailyProgress(1);
  if(typeof window.registerPracticeActivity==='function') window.registerPracticeActivity();
  renderCard();
}
wireFlashcardShell();
